// @ts-ignore The OpenNext worker is generated by the Cloudflare build.
import { default as handler } from "./.open-next/worker.js";

type CronEnv = { CRON_SECRET?: string };

const fetchHandler = typeof handler === "function" ? handler : handler.fetch;

const worker = {
  fetch: fetchHandler,
  async scheduled(_controller: unknown, env: CronEnv, ctx: ExecutionContext) {
    const secret = env.CRON_SECRET;
    if (!secret) return;
    const response = await fetchHandler(
      new Request("https://api.rentrightportal.com/api/cron/reminders", {
        method: "POST",
        headers: { authorization: `Bearer ${secret}` },
      }),
      env,
      ctx,
    );
    await response?.arrayBuffer?.();
  },
};

export default worker;
